CREATE TABLE IF NOT EXISTS "users" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"pseudo" VARCHAR(255) NOT NULL,
	"mail" VARCHAR(255) NOT NULL UNIQUE,
	"password_hash" VARCHAR(255) NOT NULL,
	"business" VARCHAR(255) NOT NULL,
	"slug" VARCHAR(255) NOT NULL UNIQUE,
	"role" VARCHAR(255) NOT NULL DEFAULT 'ARTISAN',
	"status" VARCHAR(255) NOT NULL DEFAULT 'ACTIVE',
	"mail_verified" BOOLEAN NOT NULL DEFAULT false,
	"created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "products" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"code_ref" VARCHAR(255),
	"description" TEXT,
	"price" NUMERIC(10,2) NOT NULL,
	"cost_material" NUMERIC(10,2),
	"size" VARCHAR(255),
	"stock" INTEGER NOT NULL DEFAULT 0,
	"is_visible_site" BOOLEAN NOT NULL DEFAULT false,
	"archive" BOOLEAN NOT NULL DEFAULT false,
	"user_id" INTEGER NOT NULL,
	"type_id" INTEGER NOT NULL,
	"collection_id" INTEGER,
	"finding_id" INTEGER,
	"created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "types" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"user_id" INTEGER NOT NULL,
	"created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "collections" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"user_id" INTEGER NOT NULL,
	"created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "findings" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"user_id" INTEGER NOT NULL,
	"created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "universes" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"user_id" INTEGER NOT NULL,
	"created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "materials" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"user_id" INTEGER NOT NULL,
	"created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "colors" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"user_id" INTEGER NOT NULL,
	"created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "pictures" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"url" VARCHAR(255) NOT NULL,
	"position" INTEGER NOT NULL DEFAULT 0,
	"product_id" INTEGER NOT NULL,
	"created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "places" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"type" VARCHAR(255) NOT NULL,
	"discount_rate" INTEGER,
	"commission_rate" INTEGER,
	"user_id" INTEGER NOT NULL,
	"created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "events" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"type" VARCHAR(255) NOT NULL,
	"date_beginning" DATE NOT NULL,
	"date_end" DATE,
	"status" VARCHAR(255) NOT NULL DEFAULT 'IN_PROGRESS',
	"fees" NUMERIC(10,2),
	"commission_rate" INTEGER,
	"user_id" INTEGER NOT NULL,
	"place_id" INTEGER NOT NULL,
	"created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "sales" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"sale_date" DATE NOT NULL,
	"quantity" INTEGER NOT NULL,
	"price_paid" NUMERIC(10,2) NOT NULL,
	"price_catalog" NUMERIC(10,2) NOT NULL,
	"paid_type" VARCHAR(255) NOT NULL,
	"event_id" INTEGER NOT NULL,
	"product_id" INTEGER NOT NULL,
	"created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "product_universes" (
	"product_id" INTEGER NOT NULL,
	"universe_id" INTEGER NOT NULL,
	PRIMARY KEY("product_id", "universe_id")
);

CREATE TABLE IF NOT EXISTS "product_materials" (
	"product_id" INTEGER NOT NULL,
	"material_id" INTEGER NOT NULL,
	PRIMARY KEY("product_id", "material_id")
);

CREATE TABLE IF NOT EXISTS "product_colors" (
	"product_id" INTEGER NOT NULL,
	"color_id" INTEGER NOT NULL,
	PRIMARY KEY("product_id", "color_id")
);

CREATE TABLE IF NOT EXISTS "deposits" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"event_id" INTEGER NOT NULL,
	"product_id" INTEGER NOT NULL,
	"quantity_deposited" INTEGER NOT NULL,
	"created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE UNIQUE INDEX "deposits_index_0"
ON "deposits" ("event_id", "product_id");

